command:
$keepPids = @(19176, 10072, 19152)
$killed = @()
Get-Process -Name 'claude' -ErrorAction SilentlyContinue | Where-Object {
  $_.MainWindowHandle -eq 0 -and $_.Id -notin $keepPids
} | ForEach-Object {
  Write-Host "Killing claude PID $($_.Id) ($($_.Description))"
  Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
  $killed += $_.Id
}
Write-Host "Trimmed $($killed.Count) idle claude.exe processes: $($killed -join ', ')"
# Report remaining
$rem = Get-Process -Name 'claude' -ErrorAction SilentlyContinue | Select-Object Id,CPU,WorkingSet
Write-Host "Remaining claude processes: $($rem.Count)"; $rem | Format-Table
